  -V, --verbose                      output extra information about what gomplate is doing
      --config string                config file (overridden by commandline flags) (default ".gomplate.yaml")
  -h, --help                         help for gomplate
  -v, --version                      version for gomplate
`

const usageText = `Usage:
  gomplate [flags]

Flags:
  -d, --datasource datasource        datasource in alias=URL form. Specify multiple times to add multiple sources.
  -H, --datasource-header header     HTTP header field in 'alias=Name: value' form to be provided on HTTP-based data sources. Multiples can be set.
  -c, --context datasource           pre-load a datasource into the context, in alias=URL form. Use the special alias ` + "`" + `.` + "`" + ` to set the root context.
      --plugin strings               plug in an external command as a function in name=path form. Can be specified multiple times
  -f, --file file                    Template file to process. Omit to use standard input, or use --in or --input-dir (default [-])
  -i, --in string                    Template string to process (alternative to --file and --input-dir)
      --input-dir directory          directory which is examined recursively for templates (alternative to --file and --in)
      --exclude strings              glob of files to not parse
      --exclude-processing strings   glob of files to be copied without parsing
      --include strings              glob of files to parse
  -o, --out file                     output file name. Omit to use standard output. (default [-])
  -t, --template strings             Additional template file(s)
      --output-dir directory         directory to store the processed templates. Only used for --input-dir (default ".")
      --output-map string            Template string to map the input file to an output path
      --chmod string                 set the mode for output file(s). Omit to inherit from input file(s)
      --exec-pipe                    pipe the output to the post-run exec command
      --left-delim delimiter         override the default left-delimiter [$GOMPLATE_LEFT_DELIM] (default "{{")
      --right-delim delimiter        override the default right-delimiter [$GOMPLATE_RIGHT_DELIM] (default "}}")
      --missing-key string           Control the behavior during execution if a map is indexed with a key that is not present in the map. error (default) - return an error, zero - fallback to zero value, default/invalid - print <no value> (default "error")
      --experimental                 enable experimental features [$GOMPLATE_EXPERIMENTAL]
  -V, --verbose                      output extra information about what gomplate is doing
      --config string                config file (overridden by commandline flags) (default ".gomplate.yaml")
  -h, --help                         help for gomplate
  -v, --version                      version for gomplate
`

type DataSource struct {
    Alias   string
    URL     string
    Header  map[string][]string
    cached  any
    raw     []byte
    loaded  bool
}

type PluginConfig struct {
    Cmd     string
    Args    []string
    Pipe    bool
    Timeout time.Duration
}

type Config struct {
    In                *string
    InputFiles        []string
    OutputFiles       []string
    InputDir          string
    OutputDir         string
    OutputMap         string
    Chmod             string
    Excludes          []string
    Includes          []string
    ExcludeProcessing []string
    Datasources       map[string]*DataSource
    Context           map[string]*DataSource
    Templates         map[string]*DataSource
    Plugins           map[string]*PluginConfig
    PluginTimeout     time.Duration
    ExecPipe          bool
    Experimental      bool
    Verbose           bool
    LeftDelim         string
    RightDelim        string
    MissingKey        string
    PostExec          []string
}

type cliOverrides struct {
    inSet, inputDirSet, outputDirSet, outputMapSet, chmodSet bool
    leftSet, rightSet, missingSet bool
    execPipeSet, experimentalSet bool
}

type App struct {
    cfg        *Config
    tmpl       *template.Template
    stdinOnce  bool
    stdinBytes []byte
}

func defaultConfig() *Config {
    left := os.Getenv("GOMPLATE_LEFT_DELIM")
    if left == "" { left = "{{" }
    right := os.Getenv("GOMPLATE_RIGHT_DELIM")
    if right == "" { right = "}}" }
    exp := strings.EqualFold(os.Getenv("GOMPLATE_EXPERIMENTAL"), "true")
    return &Config{
        InputFiles: []string{"-"}, OutputFiles: []string{"-"}, OutputDir: ".",
        Datasources: map[string]*DataSource{}, Context: map[string]*DataSource{}, Templates: map[string]*DataSource{}, Plugins: map[string]*PluginConfig{},
        PluginTimeout: 5 * time.Second, LeftDelim: left, RightDelim: right, MissingKey: "error", Experimental: exp,
    }
}

func main() {
    if err := run(os.Args[1:]); err != nil {
        os.Exit(1)
    }
}

func run(args []string) error {
    // Quick public help/version path.
    for _, a := range args {
        if a == "--help" || a == "-h" {
            fmt.Print(helpText)
            return nil
        }
        if a == "--version" || a == "-v" {
            fmt.Println(versionString)
            return nil
        }
    }

    cfgPath, cfgExplicit := preliminaryConfigPath(args)
    cfg := defaultConfig()
    if cfgPath != "" {
        if b, err := os.ReadFile(cfgPath); err == nil {
            if err := applyConfigYAML(cfg, b); err != nil {
                logError(fmt.Errorf("failed to parse config: %w", err))
                return err
            }
        } else if cfgExplicit {
            fmt.Print(usageText)
            fmt.Fprintf(os.Stderr, "Error: config file requested, but couldn't be opened: %v\n", err)
            logError(fmt.Errorf("config file requested, but couldn't be opened: %w", err))
            return err
        }
    }

    overrides, err := parseArgs(cfg, args)
    if err != nil {
        fmt.Print(usageText)
        if strings.HasPrefix(err.Error(), "unknown command") {
            fmt.Fprintf(os.Stderr, "Error: %s for \"gomplate\"\n", err.Error())
            fmt.Fprintf(os.Stderr, "ERROR  err=%q\n", fmt.Sprintf("%s for \"gomplate\"", err.Error()))
        } else {
            fmt.Fprintf(os.Stderr, "Error: %s\n", err)
            fmt.Fprintf(os.Stderr, "ERROR  err=%q\n", err.Error())
        }
        return err
    }
    _ = overrides
    normalizeConfig(cfg)
    if err := validateConfig(cfg); err != nil {
        logError(fmt.Errorf("failed to validate config: %s", errWithConfig(err, cfg)))
        return err
    }

    app := &App{cfg: cfg}
    if err := app.execute(); err != nil {
        logError(err)
        return err
    }
    return nil
}

func preliminaryConfigPath(args []string) (string, bool) {
    val, explicit := os.Getenv("GOMPLATE_CONFIG"), false
    if val == "" && os.Getenv("GOMPLATE_CONFIG") == "" {
        val = ".gomplate.yaml"
    }
    for i := 0; i < len(args); i++ {
        a := args[i]
        if a == "--" { break }
        if a == "--config" {
            explicit = true
            if i+1 < len(args) { val = args[i+1] }
        } else if strings.HasPrefix(a, "--config=") {
            explicit = true
            val = strings.TrimPrefix(a, "--config=")
        }
    }
    if os.Getenv("GOMPLATE_CONFIG") != "" { explicit = true }
    return val, explicit
}

func parseArgs(cfg *Config, args []string) (*cliOverrides, error) {
    ov := &cliOverrides{}
    for i := 0; i < len(args); i++ {
        a := args[i]
        if a == "--" {
            if i+1 < len(args) { cfg.PostExec = append([]string{}, args[i+1:]...) }
            return ov, nil
        }
        if a == "" { continue }
        if !strings.HasPrefix(a, "-") {
            return ov, fmt.Errorf("unknown command %q", a)
        }
        name, val, hasVal := splitFlag(a)
        need := func() (string, error) {
            if hasVal { return val, nil }
            if i+1 >= len(args) { return "", fmt.Errorf("flag needs an argument: %s", name) }
            i++
            return args[i], nil
        }
        switch name {
        case "-d", "--datasource":
            v, e := need(); if e != nil { return ov, e }
            ds := parseDatasourceSpec(v)
            cfg.Datasources[ds.Alias] = ds
        case "-H", "--datasource-header":
            v, e := need(); if e != nil { return ov, e }
            alias, hn, hv := parseHeaderSpec(v)
            if alias != "" && hn != "" {
                ds := cfg.Datasources[alias]
                if ds == nil { ds = &DataSource{Alias: alias, Header: map[string][]string{}}; cfg.Datasources[alias] = ds }
                if ds.Header == nil { ds.Header = map[string][]string{} }
                ds.Header[hn] = append(ds.Header[hn], hv)
            }
        case "-c", "--context":
            v, e := need(); if e != nil { return ov, e }
            ds := parseDatasourceSpec(v)
            cfg.Context[ds.Alias] = ds
        case "--plugin":
            v, e := need(); if e != nil { return ov, e }
            n, p := splitAlias(v)
            if n != "" { cfg.Plugins[n] = &PluginConfig{Cmd: p, Timeout: cfg.PluginTimeout} }
        case "-f", "--file":
            v, e := need(); if e != nil { return ov, e }
            if len(cfg.InputFiles) == 1 && cfg.InputFiles[0] == "-" && cfg.In == nil { cfg.InputFiles = nil }
            cfg.InputFiles = append(cfg.InputFiles, v)
        case "-i", "--in":
            v, e := need(); if e != nil { return ov, e }
            cfg.In = &v; ov.inSet = true
        case "--input-dir":
            v, e := need(); if e != nil { return ov, e }
            cfg.InputDir = v; ov.inputDirSet = true
        case "--exclude":
            v, e := need(); if e != nil { return ov, e }
            cfg.Excludes = append(cfg.Excludes, v)
        case "--exclude-processing":
            v, e := need(); if e != nil { return ov, e }
            cfg.ExcludeProcessing = append(cfg.ExcludeProcessing, v)
        case "--include":
            v, e := need(); if e != nil { return ov, e }
            cfg.Includes = append(cfg.Includes, v)
        case "-o", "--out":
            v, e := need(); if e != nil { return ov, e }
            if len(cfg.OutputFiles) == 1 && cfg.OutputFiles[0] == "-" { cfg.OutputFiles = nil }
            cfg.OutputFiles = append(cfg.OutputFiles, v)
        case "-t", "--template":
            v, e := need(); if e != nil { return ov, e }
            ds := parseDatasourceSpec(v)
            cfg.Templates[ds.Alias] = ds
        case "--output-dir":
            v, e := need(); if e != nil { return ov, e }
            cfg.OutputDir = v; ov.outputDirSet = true
        case "--output-map":
            v, e := need(); if e != nil { return ov, e }
            cfg.OutputMap = v; ov.outputMapSet = true
        case "--chmod":
            v, e := need(); if e != nil { return ov, e }
            cfg.Chmod = v; ov.chmodSet = true
        case "--exec-pipe":
            cfg.ExecPipe = true; ov.execPipeSet = true
        case "--left-delim":
            v, e := need(); if e != nil { return ov, e }
            cfg.LeftDelim = v; ov.leftSet = true
        case "--right-delim":
            v, e := need(); if e != nil { return ov, e }
            cfg.RightDelim = v; ov.rightSet = true
        case "--missing-key":
            v, e := need(); if e != nil { return ov, e }
            cfg.MissingKey = v; ov.missingSet = true
        case "--experimental":
            cfg.Experimental = true; ov.experimentalSet = true
        case "-V", "--verbose":
            cfg.Verbose = true
        case "--config":
            _, e := need(); if e != nil { return ov, e }
        default:
            return ov, fmt.Errorf("unknown flag: %s", name)
        }
    }
    return ov, nil
}

func splitFlag(a string) (name, val string, has bool) {
    if strings.HasPrefix(a, "--") {
        if idx := strings.IndexByte(a, '='); idx >= 0 { return a[:idx], a[idx+1:], true }
        return a, "", false
    }
    // support short flag with attached value only for forms like -iX poorly; most tests use separated values.
    return a, "", false
}

func splitAlias(s string) (string, string) {
    if idx := strings.IndexByte(s, '='); idx >= 0 { return s[:idx], s[idx+1:] }
    return "", s
}

func parseDatasourceSpec(s string) *DataSource {
    alias, u := splitAlias(s)
    if alias == "" {
        u = s
        alias = implicitAlias(u)
    }
    return &DataSource{Alias: alias, URL: u, Header: map[string][]string{}}
}

func implicitAlias(u string) string {
    noQuery := strings.SplitN(u, "?", 2)[0]
    if strings.HasPrefix(noQuery, "file://") {
        if parsed, err := url.Parse(noQuery); err == nil { noQuery = parsed.Path }
    }
    noQuery = strings.TrimRight(noQuery, "/")
    base := filepath.Base(noQuery)
    ext := filepath.Ext(base)
    if ext != "" { base = strings.TrimSuffix(base, ext) }
    if base == "." || base == string(filepath.Separator) || base == "" { base = "data" }
    return base
}

func parseHeaderSpec(s string) (alias, name, value string) {
    a, rest := splitAlias(s)
    if i := strings.Index(rest, ":"); i >= 0 {
        return a, strings.TrimSpace(rest[:i]), strings.TrimSpace(rest[i+1:])
    }
    return a, rest, ""
}

func normalizeConfig(cfg *Config) {
    if cfg.InputFiles == nil && cfg.In == nil && cfg.InputDir == "" { cfg.InputFiles = []string{"-"} }
    if cfg.OutputFiles == nil && cfg.InputDir == "" { cfg.OutputFiles = []string{"-"} }
    if cfg.OutputDir == "" { cfg.OutputDir = "." }
    if cfg.LeftDelim == "" { cfg.LeftDelim = "{{" }
    if cfg.RightDelim == "" { cfg.RightDelim = "}}" }
    if cfg.MissingKey == "" { cfg.MissingKey = "error" }
    if cfg.PluginTimeout == 0 { cfg.PluginTimeout = 5 * time.Second }
    for _, p := range cfg.Plugins { if p.Timeout == 0 { p.Timeout = cfg.PluginTimeout } }
}

func validateConfig(cfg *Config) error {
    choices := 0
    var names []string
    if cfg.In != nil { choices++; names = append(names, "'in'") }
    if cfg.InputDir != "" { choices++; names = append(names, "'inputDir'") }
    if len(cfg.InputFiles) > 0 && !(len(cfg.InputFiles)==1 && cfg.InputFiles[0]=="-" && cfg.In != nil) { choices++; names = append(names, "'inputFiles'") }
    if choices > 1 { return fmt.Errorf("only one of these options is supported at a time: %s", strings.Join(names, ", ")) }
    if cfg.InputDir == "" && cfg.In == nil && len(cfg.InputFiles) != len(cfg.OutputFiles) {
        return fmt.Errorf("must provide same number of 'outputFiles' (%d) as 'in' or 'inputFiles' (%d) options", len(cfg.OutputFiles), len(cfg.InputFiles))
    }
    if cfg.In != nil && len(cfg.OutputFiles) > 1 { return fmt.Errorf("must provide only one 'outputFiles' option when using 'in'") }
    if cfg.ExecPipe && len(cfg.PostExec) == 0 { return fmt.Errorf("execPipe requires postExec") }
    return nil
}

func errWithConfig(err error, cfg *Config) string {
    // Enough of the diagnostic body to resemble gomplate for humans/tests that only inspect prefix.
    var b strings.Builder
    b.WriteString(err.Error())
    b.WriteString("\n---\n")
    if cfg.In != nil { fmt.Fprintf(&b, "in: %s\n", *cfg.In) }
    if len(cfg.InputFiles)>0 { fmt.Fprintf(&b, "inputFiles: %v\n", cfg.InputFiles) }
    if len(cfg.OutputFiles)>0 { fmt.Fprintf(&b, "outputFiles: %v\n", cfg.OutputFiles) }
    if cfg.InputDir!="" { fmt.Fprintf(&b, "inputDir: %s\n", cfg.InputDir) }
    if cfg.OutputDir!="" { fmt.Fprintf(&b, "outputDir: %s\n", cfg.OutputDir) }
    fmt.Fprintf(&b, "leftDelim: '%s'\nrightDelim: '%s'\nmissingKey: %s\npluginTimeout: %s\n", cfg.LeftDelim, cfg.RightDelim, cfg.MissingKey, cfg.PluginTimeout)
    return b.String()
}

func (a *App) execute() error {
    if a.cfg.InputDir != "" {
        return a.processDir()
    }
    outputs := a.cfg.OutputFiles
    if a.cfg.In != nil {
        if len(outputs)==0 { outputs=[]string{"-"} }
        out, err := a.renderString("<arg>", *a.cfg.In, a.defaultContext())
        if err != nil { writeOutput(outputs[0], out, a.cfg, "") ; return fmt.Errorf("renderTemplate: %w", err) }
        if a.cfg.ExecPipe { return a.runPostExecWithInput(out) }
        if err := writeOutput(outputs[0], out, a.cfg, ""); err != nil { return err }
        return a.runPostExec()
    }
    for i, in := range a.cfg.InputFiles {
        outPath := "-"
        if i < len(outputs) { outPath = outputs[i] }
        content, err := a.readTemplateInput(in)
        if err != nil { return err }
        name := in
        if in == "-" { name = "<stdin>" }
        out, err := a.renderString(name, string(content), a.defaultContext())
        if err != nil { writeOutput(outPath, out, a.cfg, in); return fmt.Errorf("renderTemplate: %w", err) }
        if a.cfg.ExecPipe { return a.runPostExecWithInput(out) }
        if err := writeOutput(outPath, out, a.cfg, in); err != nil { return err }
    }
    return a.runPostExec()
}

func (a *App) readTemplateInput(path string) ([]byte, error) {
    if path == "-" || path == "" { return io.ReadAll(os.Stdin) }
    return os.ReadFile(path)
}

func (a *App) defaultContext() any {
    ctx := map[string]any{"Env": envMap()}
    if root, ok := a.cfg.Context["."]; ok {
        val, err := a.loadDatasource(root, "", true)
        if err == nil { return val }
        return ctx
    }
    keys := make([]string,0,len(a.cfg.Context))
    for k := range a.cfg.Context { if k != "." { keys = append(keys,k) } }
    sort.Strings(keys)
    for _, k := range keys {
        val, err := a.loadDatasource(a.cfg.Context[k], "", true)
        if err == nil { ctx[k] = val }
    }
    return ctx
}

func envMap() map[string]string {
    m := map[string]string{}
    for _, e := range os.Environ() {
        if i := strings.IndexByte(e, '='); i >= 0 { m[e[:i]] = e[i+1:] }
    }
    return m
}

func (a *App) renderString(name, text string, ctx any) (string, error) {
    t := template.New(name).Delims(a.cfg.LeftDelim, a.cfg.RightDelim).Funcs(a.funcMap())
    opt := "missingkey=error"
    switch strings.ToLower(a.cfg.MissingKey) {
    case "zero": opt = "missingkey=zero"
    case "default", "invalid": opt = "missingkey=default"
    }
    t = t.Option(opt)
    if err := a.parseExternalTemplates(t); err != nil { return "", fmt.Errorf("parse template %s: %w", name, err) }
    if _, err := t.Parse(text); err != nil { return "", fmt.Errorf("parse template %s: %w", name, err) }
    var b bytes.Buffer
    err := t.ExecuteTemplate(&b, name, ctx)
    if err != nil { return b.String(), fmt.Errorf("failed to render template %s: %w", name, err) }
    return b.String(), nil
}

func (a *App) parseExternalTemplates(t *template.Template) error {
    keys := make([]string,0,len(a.cfg.Templates))
    for k := range a.cfg.Templates { keys=append(keys,k) }
    sort.Strings(keys)
    for _, alias := range keys {
        ds := a.cfg.Templates[alias]
        path := filePathFromURL(ds.URL)
        if st, err := os.Stat(path); err == nil && st.IsDir() {
            base := path
            err := filepath.WalkDir(base, func(p string, d os.DirEntry, err error) error {
                if err != nil || d.IsDir() { return err }
                b, err := os.ReadFile(p); if err != nil { return err }
                rel, _ := filepath.Rel(base, p)
                name := filepath.ToSlash(filepath.Join(alias, rel))
                _, err = t.New(name).Parse(string(b))
                return err
            })
            if err != nil { return err }
        } else {
            b, err := a.loadRaw(ds, "")
            if err != nil { return err }
            if _, err := t.New(alias).Parse(string(b)); err != nil { return err }
        }
    }
    return nil
}

func writeOutput(path, out string, cfg *Config, inputPath string) error {
    if strings.TrimSpace(out) == "" { return nil }
    if path == "" || path == "-" { _, err := io.WriteString(os.Stdout, out); return err }
    if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil { return err }
    mode := os.FileMode(0o644)
    if inputPath != "" && inputPath != "-" { if st, err := os.Stat(inputPath); err == nil { mode = st.Mode().Perm() } }
    if cfg.Chmod != "" { if m, err := parseOctalMode(cfg.Chmod); err == nil { mode = m } }
    if err := os.WriteFile(path, []byte(out), mode); err != nil { return err }
    return os.Chmod(path, mode)
}

func parseOctalMode(s string) (os.FileMode, error) {
    var v uint64
    _, err := fmt.Sscanf(s, "%o", &v)
    return os.FileMode(v), err
}

func (a *App) runPostExec() error {
    if len(a.cfg.PostExec)==0 { return nil }
    cmd := exec.Command(a.cfg.PostExec[0], a.cfg.PostExec[1:]...)
    cmd.Stdout = os.Stdout; cmd.Stderr = os.Stderr; cmd.Stdin = os.Stdin
    return cmd.Run()
}

func (a *App) runPostExecWithInput(in string) error {
    if len(a.cfg.PostExec)==0 { return nil }
    cmd := exec.Command(a.cfg.PostExec[0], a.cfg.PostExec[1:]...)
    cmd.Stdout = os.Stdout; cmd.Stderr = os.Stderr; cmd.Stdin = strings.NewReader(in)
    return cmd.Run()
}

func logError(err error) {
    if err == nil { return }
    msg := err.Error()
    switch strings.ToLower(os.Getenv("GOMPLATE_LOG_FORMAT")) {
    case "simple":
        fmt.Fprintf(os.Stderr, " error=%q\n", msg)
    case "logfmt":
        fmt.Fprintf(os.Stderr, "time=%s level=error error=%q\n", time.Now().Format(time.RFC3339), msg)
    case "console":
        fmt.Fprintf(os.Stderr, "ERR  error=%q\n", msg)
    default:
        b, _ := json.Marshal(map[string]any{"time": time.Now().UTC().Format(time.RFC3339Nano), "level": "ERROR", "msg": "", "err": msg})
        os.Stderr.Write(b); os.Stderr.Write([]byte("\n"))
    }
}

// Datasource loading
func (a *App) datasource(alias string, args ...string) (any, error) {
    ds := a.cfg.Datasources[alias]
    if ds == nil { return nil, fmt.Errorf("datasource %q not defined", alias) }
    sub := ""
    if len(args)>0 { sub = args[0] }
    return a.loadDatasource(ds, sub, true)
}

func (a *App) include(alias string, args ...string) (string, error) {
    ds := a.cfg.Datasources[alias]
    if ds == nil {
        // allow including external templates by alias-like path as a convenience
        return "", fmt.Errorf("datasource %q not defined", alias)
    }
    sub := ""
    if len(args)>0 { sub = args[0] }
    b, err := a.loadRaw(ds, sub)
    return string(b), err
}

func (a *App) loadDatasource(ds *DataSource, sub string, parse bool) (any, error) {
    if sub == "" && ds.loaded { return ds.cached, nil }
    if strings.HasPrefix(ds.URL, "merge:") && sub == "" {
        val, err := a.loadMerge(ds.URL)
        if err != nil { return nil, err }
        ds.cached=val; ds.loaded=true; return val,nil
    }
    raw, ctype, fakePath, err := a.loadRawWithType(ds, sub)
    if err != nil { return nil, err }
    if !parse { return string(raw), nil }
    val, err := parseByType(raw, fakePath, ctype)
    if err != nil { return nil, err }
    if sub == "" { ds.cached=val; ds.loaded=true; ds.raw=raw }
    return val, nil
}

func (a *App) loadMerge(u string) (any, error) {
    rest := strings.TrimPrefix(u, "merge:")
    parts := strings.Split(rest, "|")
    maps := make([]map[string]any,0,len(parts))
    for _, p := range parts {
        p = strings.TrimSpace(p)
        var val any
        var err error
        if ds := a.cfg.Datasources[p]; ds != nil { val, err = a.loadDatasource(ds, "", true) } else { val, err = a.loadDatasource(parseDatasourceSpec("_="+p), "", true) }
        if err != nil { return nil, err }
        m, ok := toStringAnyMap(val); if !ok { return nil, fmt.Errorf("merge datasource %s did not produce a map", p) }
        maps = append(maps, m)
    }
    out := map[string]any{}
    for i := len(maps)-1; i>=0; i-- { out = mergeMaps(out, maps[i]) }
    return out,nil
}

func (a *App) loadRaw(ds *DataSource, sub string) ([]byte, error) {
    b, _, _, err := a.loadRawWithType(ds, sub)
    return b, err
}

func (a *App) loadRawWithType(ds *DataSource, sub string) ([]byte, string, string, error) {
    u := ds.URL
    scheme := schemeOf(u)
    if scheme == "" || scheme == "file" {
        path := filePathFromURL(u)
        q := queryFromURL(u)
        if sub != "" { path = filepath.Join(path, sub) }
        st, err := os.Stat(path)
        if err == nil && st.IsDir() {
            entries, err := os.ReadDir(path); if err != nil { return nil,"","",err }
            names := []string{}
            for _, e := range entries { names = append(names, e.Name()) }
            sort.Strings(names)
            return []byte(fmt.Sprint(names)), q.Get(typeParam()), path, nil
        }
        b, err := os.ReadFile(path)
        return b, q.Get(typeParam()), path, err
    }
    if scheme == "env" {
        name := envNameFromURL(u)
        val := os.Getenv(name)
        q := queryFromURL(u)
        return []byte(val), q.Get(typeParam()), name, nil
    }
    if scheme == "stdin" {
        if !a.stdinOnce { b, _ := io.ReadAll(os.Stdin); a.stdinBytes=b; a.stdinOnce=true }
        q := queryFromURL(u)
        fake := stdinPathFromURL(u)
        return a.stdinBytes, q.Get(typeParam()), fake, nil
    }
    if scheme == "http" || scheme == "https" {
        req, err := http.NewRequestWithContext(context.Background(), "GET", u, nil); if err != nil { return nil,"","",err }
        for k, vals := range ds.Header { for _, v := range vals { req.Header.Add(k, v) } }
        resp, err := http.DefaultClient.Do(req); if err != nil { return nil,"","",err }
        defer resp.Body.Close()
        b, err := io.ReadAll(resp.Body); if err != nil { return nil,"","",err }
        if resp.StatusCode < 200 || resp.StatusCode >= 300 { return nil,"","",fmt.Errorf("GET %s: %s", u, resp.Status) }
        q := queryFromURL(u)
        ctype := q.Get(typeParam())
        if ctype=="" { ctype = resp.Header.Get("Content-Type") }
        return b, ctype, u, nil
    }
    return nil,"","",fmt.Errorf("unsupported datasource scheme %q", scheme)
}

func typeParam() string { if v:=os.Getenv("GOMPLATE_TYPE_PARAM"); v!="" { return v }; return "type" }

func schemeOf(u string) string {
    if i := strings.Index(u, ":"); i>0 {
        s := u[:i]
        if strings.IndexAny(s, "/\\") < 0 { return s }
    }
    return ""
}

func queryFromURL(u string) url.Values {
    if parsed, err := url.Parse(u); err == nil { return parsed.Query() }
    if i := strings.IndexByte(u, '?'); i>=0 { q,_:=url.ParseQuery(u[i+1:]); return q }
    return url.Values{}
}

func filePathFromURL(u string) string {
    if strings.HasPrefix(u, "file://") { if p, err := url.Parse(u); err == nil { return p.Path } }
    if i := strings.IndexByte(u, '?'); i >= 0 { u = u[:i] }
    return u
}

func envNameFromURL(u string) string {
    rest := strings.TrimPrefix(u, "env:")
    if strings.HasPrefix(rest, "//") { if p, err := url.Parse(u); err == nil { return strings.TrimLeft(p.Path, "/") } }
    if i := strings.IndexByte(rest, '?'); i>=0 { rest = rest[:i] }
    return strings.TrimLeft(rest, "/")
}

func stdinPathFromURL(u string) string {
    if p, err := url.Parse(u); err == nil { return p.Path }
    return u
}

func parseByType(b []byte, path, ctype string) (any, error) {
    ct := strings.ToLower(strings.TrimSpace(strings.Split(ctype, ";")[0]))
    if ct == "" {
        switch strings.ToLower(filepath.Ext(path)) {
        case ".json": ct="application/json"
        case ".yaml", ".yml": ct="application/yaml"
        case ".toml": ct="application/toml"
        case ".csv": ct="text/csv"
        case ".env": ct="application/x-env"
        default: ct="text/plain"
        }
    }
    s := string(b)
    switch ct {
    case "application/json", "text/json":
        var v any; if err := json.Unmarshal(b, &v); err != nil { return nil, err }; return v,nil
    case "application/array+json":
        var v []any; if err := json.Unmarshal(b, &v); err != nil { return nil, err }; return v,nil
    case "application/yaml", "application/x-yaml", "text/yaml", "text/x-yaml":
        return parseYAML(s)
    case "application/toml":
        return parseTOML(s)
    case "text/csv":
        r := csv.NewReader(strings.NewReader(s)); return r.ReadAll()
    case "application/x-env":
        return parseEnvFile(s), nil
    default:
        return s, nil
    }
}

func (a *App) processDir() error {
    inDir := a.cfg.InputDir
    return filepath.WalkDir(inDir, func(path string, d os.DirEntry, err error) error {
        if err != nil { return err }
        if d.IsDir() { return nil }
        rel, _ := filepath.Rel(inDir, path)
        relSlash := filepath.ToSlash(rel)
        if !includedByPatterns(relSlash, a.cfg.Includes, a.cfg.Excludes) { return nil }
        outPath := filepath.Join(a.cfg.OutputDir, rel)
        if a.cfg.OutputMap != "" {
            omctx := a.outputMapContext(relSlash)
            rendered, err := a.renderString("<output-map>", a.cfg.OutputMap, omctx)
            if err != nil { return fmt.Errorf("renderTemplate: %w", err) }
            outPath = strings.TrimSpace(rendered)
        }
        if matchesAny(relSlash, a.cfg.ExcludeProcessing) {
            b, err := os.ReadFile(path); if err != nil { return err }
            if err := os.MkdirAll(filepath.Dir(outPath), 0o755); err != nil { return err }
            mode := os.FileMode(0o644); if st,err:=os.Stat(path); err==nil { mode=st.Mode().Perm() }
            if a.cfg.Chmod!="" { if m,err:=parseOctalMode(a.cfg.Chmod); err==nil { mode=m } }
            if strings.TrimSpace(string(b))=="" { return nil }
            if err := os.WriteFile(outPath,b,mode); err != nil { return err }
            return os.Chmod(outPath,mode)
        }
        b, err := os.ReadFile(path); if err != nil { return err }
        out, err := a.renderString(path, string(b), a.defaultContext())
        if err != nil { writeOutput(outPath,out,a.cfg,path); return fmt.Errorf("renderTemplate: %w", err) }
        return writeOutput(outPath,out,a.cfg,path)
    })
}

func (a *App) outputMapContext(rel string) map[string]any {
    base := map[string]any{"in": rel, "ctx": a.defaultContext()}
    if m, ok := a.defaultContext().(map[string]any); ok {
        for k,v := range m { if k!="in" && k!="ctx" { base[k]=v } }
    }
    return base
}

func includedByPatterns(rel string, includes, excludes []string) bool {
    if len(includes)>0 && !matchesAny(rel, includes) { return false }
    included := true
    for _, p := range excludes {
        neg := strings.HasPrefix(p, "!")
        if neg { p = strings.TrimPrefix(p,"!") }
        if matchPattern(rel,p) { included = neg }
    }
    return included
}

func matchesAny(rel string, patterns []string) bool { for _, p := range patterns { if matchPattern(rel,p) { return true } }; return false }
func matchPattern(rel, pattern string) bool {
    rel = filepath.ToSlash(rel); pattern = filepath.ToSlash(pattern)
    if ok,_ := filepath.Match(pattern, rel); ok { return true }
    if !strings.Contains(pattern,"/") { if ok,_ := filepath.Match(pattern, filepath.Base(rel)); ok { return true } }
    return false
}
EOF"}

