func seqVariadic(args ...any) []int64 {
    var start,end,step int64
    switch len(args) {
    case 0: return []int64{}
    case 1: start=1; end=toInt64(args[0]); step=1
    case 2: start=toInt64(args[0]); end=toInt64(args[1]); step=1
    default: start=toInt64(args[0]); end=toInt64(args[1]); step=toInt64(args[2])
    }
    if step==0 { return []int64{} }
    if end < start && step > 0 { step = -step }
    if end > start && step < 0 { step = -step }
    end -= (end - start) % step
    out := []int64{start}
    for out[len(out)-1] != end { out = append(out, out[len(out)-1]+step) }
    return out
}

