func (UUIDNS) V4() (string,error) { var b [16]byte; if _,err:=rand.Read(b[:]); err!=nil { return "",err }; b[6]=(b[6]&0x0f)|0x40; b[8]=(b[8]&0x3f)|0x80; return fmt.Sprintf("%08x-%04x-%04x-%04x-%012x", b[0:4], b[4:6], b[6:8], b[8:10], b[10:16]),nil }

func runPlugin(pc *PluginConfig, args ...any) (string,error) {
    if pc == nil || pc.Cmd == "" { return "", errors.New("plugin command not configured") }
    argv := append([]string{}, pc.Args...)
    var stdin string
    vals := make([]string,len(args)); for i,a:= range args { vals[i]=toString(a) }
    if pc.Pipe && len(vals)>0 { stdin=vals[len(vals)-1]; vals=vals[:len(vals)-1] }
    argv = append(argv, vals...)
    cmd := exec.Command(pc.Cmd, argv...)
    if stdin!="" { cmd.Stdin = strings.NewReader(stdin) }
    var out, er bytesBuffer
    cmd.Stdout = &out; cmd.Stderr = &er
    if pc.Timeout > 0 {
        done := make(chan error,1)
        if err:=cmd.Start(); err!=nil { return "",err }
        go func(){ done<-cmd.Wait() }()
        select { case err:=<-done: if er.String()!="" { fmt.Fprint(os.Stderr, er.String()) }; return out.String(),err
        case <-time.After(pc.Timeout): _=cmd.Process.Kill(); return out.String(), fmt.Errorf("plugin timed out") }
    }
    err := cmd.Run(); if er.String()!="" { fmt.Fprint(os.Stderr, er.String()) }; return out.String(),err
}

type bytesBuffer struct{ strings.Builder }
func (b *bytesBuffer) Write(p []byte) (int,error) { return b.Builder.Write(p) }

// Utility conversions
func toString(v any) string {
    if v == nil { return "" }
    switch x:=v.(type) { case string: return x; case []byte: return string(x); case fmt.Stringer: return x.String(); default: return fmt.Sprint(v) }
}
func number(v any) (float64,bool) {
    switch x:=v.(type) {
    case int: return float64(x),true; case int8: return float64(x),true; case int16: return float64(x),true; case int32: return float64(x),true; case int64: return float64(x),true
    case uint: return float64(x),true; case uint8: return float64(x),true; case uint16: return float64(x),true; case uint32: return float64(x),true; case uint64: return float64(x),true
    case float32: return float64(x),false; case float64: return x,false
    case json.Number: f,_:=x.Float64(); return f, strings.IndexAny(string(x),".eE")<0
    case string: if i,err:=strconv.ParseInt(x,10,64); err==nil { return float64(i),true }; f,_:=strconv.ParseFloat(x,64); return f,false
    default: rv:=reflect.ValueOf(v); if rv.IsValid() { switch rv.Kind(){ case reflect.Int,reflect.Int8,reflect.Int16,reflect.Int32,reflect.Int64: return float64(rv.Int()),true; case reflect.Uint,reflect.Uint8,reflect.Uint16,reflect.Uint32,reflect.Uint64: return float64(rv.Uint()),true; case reflect.Float32,reflect.Float64: return rv.Float(),false } }; return 0,true }
}
func toInt64(v any) int64 { f,_:=number(v); return int64(f) }
func numResult(f float64, allInt bool) any { if allInt || math.Trunc(f)==f { return int64(f) }; return f }
func toAnySlice(v any) ([]any,error) { if v==nil { return nil,fmt.Errorf("expected an array or slice, but got <nil>") }; if a,ok:=v.([]any); ok { return append([]any{},a...),nil }; rv:=reflect.ValueOf(v); if rv.Kind()!=reflect.Slice && rv.Kind()!=reflect.Array { return nil,fmt.Errorf("expected an array or slice, but got %s", rv.Kind()) }; out:=make([]any,rv.Len()); for i:=0;i<rv.Len();i++ { out[i]=rv.Index(i).Interface() }; return out,nil }
func toStringSlice(v any) []string { arr,err:=toAnySlice(v); if err!=nil { return nil }; out:=make([]string,len(arr)); for i,a:=range arr { out[i]=toString(a) }; return out }
func toStringAnyMap(v any) (map[string]any,bool) { if v==nil { return nil,false }; if m,ok:=v.(map[string]any); ok { return m,true }; if m,ok:=v.(map[string]string); ok { out:=map[string]any{}; for k,v:=range m { out[k]=v }; return out,true }; rv:=reflect.ValueOf(v); if rv.Kind()==reflect.Map && rv.Type().Key().Kind()==reflect.String { out:=map[string]any{}; for _,k:=range rv.MapKeys(){ out[k.String()]=rv.MapIndex(k).Interface() }; return out,true }; return nil,false }
func mergeMaps(dst, src map[string]any) map[string]any { out:=map[string]any{}; for k,v:=range dst { out[k]=v }; for k,v:=range src { if sm,ok:=toStringAnyMap(v); ok { if dm,ok:=toStringAnyMap(out[k]); ok { out[k]=mergeMaps(dm,sm); continue } }; out[k]=v }; return out }
func collHas(haystack, needle any) bool { if m,ok:=toStringAnyMap(haystack); ok { _,ok:=m[toString(needle)]; return ok }; arr,err:=toAnySlice(haystack); if err==nil { for _,v:= range arr { if reflect.DeepEqual(v,needle) || toString(v)==toString(needle) { return true } } }; return false }
func truthy(v any) bool { if v==nil { return false }; rv:=reflect.ValueOf(v); switch rv.Kind(){ case reflect.Bool: return rv.Bool(); case reflect.String,reflect.Array,reflect.Slice,reflect.Map: return rv.Len()!=0; case reflect.Int,reflect.Int8,reflect.Int16,reflect.Int32,reflect.Int64: return rv.Int()!=0; case reflect.Uint,reflect.Uint8,reflect.Uint16,reflect.Uint32,reflect.Uint64: return rv.Uint()!=0; case reflect.Float32,reflect.Float64: return rv.Float()!=0 }; return true }
func defaultFunc(def, v any) any { if truthy(v) { return v }; return def }
func requiredFunc(msg string, v any) (any,error) { if !truthy(v) { return nil,errors.New(msg) }; return v,nil }
EOF"}

