func runPlugin(pc *PluginConfig, args ...any) (string,error) {
    if pc == nil || pc.Cmd == "" { return "", errors.New("plugin command not configured") }
    argv := append([]string{}, pc.Args...)
    var stdin string
    vals := make([]string,len(args)); for i,a:= range args { vals[i]=toString(a) }
    if pc.Pipe && len(vals)>0 { stdin=vals[len(vals)-1]; vals=vals[:len(vals)-1] }
    argv = append(argv, vals...)
    cmd := exec.Command(pc.Cmd, argv...)
    if stdin!="" { cmd.Stdin = strings.NewReader(stdin) }
    var out, er bytesBuffer
    cmd.Stdout = &out; cmd.Stderr = &er
    if pc.Timeout > 0 {
        done := make(chan error,1)
        if err:=cmd.Start(); err!=nil { return "",err }
        go func(){ done<-cmd.Wait() }()
        select { case err:=<-done: if er.String()!="" { fmt.Fprint(os.Stderr, er.String()) }; return out.String(),err
        case <-time.After(pc.Timeout): _=cmd.Process.Kill(); return out.String(), fmt.Errorf("plugin timed out") }
    }
    err := cmd.Run(); if er.String()!="" { fmt.Fprint(os.Stderr, er.String()) }; return out.String(),err
}

