func toStringAnyMap(v any) (map[string]any,bool) { if v==nil { return nil,false }; if m,ok:=v.(map[string]any); ok { return m,true }; if m,ok:=v.(map[string]string); ok { out:=map[string]any{}; for k,v:=range m { out[k]=v }; return out,true }; rv:=reflect.ValueOf(v); if rv.Kind()==reflect.Map && rv.Type().Key().Kind()==reflect.String { out:=map[string]any{}; for _,k:=range rv.MapKeys(){ out[k.String()]=rv.MapIndex(k).Interface() }; return out,true }; return nil,false }
func mergeMaps(dst, src map[string]any) map[string]any { out:=map[string]any{}; for k,v:=range dst { out[k]=v }; for k,v:=range src { if sm,ok:=toStringAnyMap(v); ok { if dm,ok:=toStringAnyMap(out[k]); ok { out[k]=mergeMaps(dm,sm); continue } }; out[k]=v }; return out }
func collHas(haystack, needle any) bool { if m,ok:=toStringAnyMap(haystack); ok { _,ok:=m[toString(needle)]; return ok }; arr,err:=toAnySlice(haystack); if err==nil { for _,v:= range arr { if reflect.DeepEqual(v,needle) || toString(v)==toString(needle) { return true } } }; return false }
func truthy(v any) bool { if v==nil { return false }; rv:=reflect.ValueOf(v); switch rv.Kind(){ case reflect.Bool: return rv.Bool(); case reflect.String,reflect.Array,reflect.Slice,reflect.Map: return rv.Len()!=0; case reflect.Int,reflect.Int8,reflect.Int16,reflect.Int32,reflect.Int64: return rv.Int()!=0; case reflect.Uint,reflect.Uint8,reflect.Uint16,reflect.Uint32,reflect.Uint64: return rv.Uint()!=0; case reflect.Float32,reflect.Float64: return rv.Float()!=0 }; return true }
func defaultFunc(def, v any) any { if truthy(v) { return v }; return def }
func requiredFunc(msg string, v any) (any,error) { if !truthy(v) { return nil,errors.New(msg) }; return v,nil }
