package main

import (
    "fmt"
    "sort"
    "strconv"
    "strings"
    "time"
)

type yamlLine struct { indent int; text string; raw string }

func parseYAML(s string) (any,error) {
    lines := yamlPreprocess(s)
    if len(lines)==0 { return map[string]any{}, nil }
    v,_,err := parseYAMLBlock(lines,0,lines[0].indent)
    return v,err
}

func yamlPreprocess(s string) []yamlLine {
    s = strings.ReplaceAll(s, "\r\n", "\n")
    out := []yamlLine{}
    for _, raw := range strings.Split(s,"\n") {
        raw = strings.TrimRight(raw, "\r")
        if strings.TrimSpace(raw)=="" { continue }
        trimmedRaw := strings.TrimLeft(raw, " ")
        if strings.HasPrefix(trimmedRaw,"#") { continue }
        noComment := stripYAMLComment(raw)
        if strings.TrimSpace(noComment)=="" { continue }
        ind := len(noComment) - len(strings.TrimLeft(noComment," "))
        out = append(out, yamlLine{indent: ind, text: strings.TrimSpace(noComment), raw: noComment})
    }
    return out
}

func stripYAMLComment(s string) string {
    inS,inD,esc := false,false,false
    for i,r := range s {
        if esc { esc=false; continue }
        if r=='\\' { esc=true; continue }
        if r=='\'' && !inD { inS=!inS; continue }
        if r=='"' && !inS { inD=!inD; continue }
        if r=='#' && !inS && !inD {
            if i==0 || s[i-1]==' ' || s[i-1]=='\t' { return strings.TrimRight(s[:i]," ") }
        }
    }
    return s
}

func parseYAMLBlock(lines []yamlLine, idx, indent int) (any,int,error) {
    if idx>=len(lines) { return nil,idx,nil }
    if strings.HasPrefix(lines[idx].text,"- ") && lines[idx].indent==indent { return parseYAMLList(lines,idx,indent) }
    return parseYAMLMap(lines,idx,indent)
}

func parseYAMLMap(lines []yamlLine, idx, indent int) (map[string]any,int,error) {
    m := map[string]any{}
    for idx < len(lines) {
        ln := lines[idx]
        if ln.indent < indent { break }
        if ln.indent > indent { break }
        if strings.HasPrefix(ln.text,"- ") { break }
        key, rest, ok := splitYAMLKey(ln.text)
        if !ok { idx++; continue }
        if rest == "" {
            if idx+1 < len(lines) && lines[idx+1].indent > indent {
                v,next,err := parseYAMLBlock(lines, idx+1, lines[idx+1].indent); if err!=nil { return nil,next,err }
                m[key]=v; idx=next
            } else { m[key]=map[string]any{}; idx++ }
        } else if rest == "|" || rest == "|-" || rest == "|+" || strings.HasPrefix(rest, ">") {
            val,next := collectBlockScalar(lines, idx+1, indent, strings.HasPrefix(rest, ">"), strings.HasSuffix(rest,"-"))
            m[key]=val; idx=next
        } else {
            m[key] = parseScalar(rest); idx++
        }
    }
    return m,idx,nil
}

func parseYAMLList(lines []yamlLine, idx, indent int) ([]any,int,error) {
    arr := []any{}
    for idx < len(lines) {
        ln := lines[idx]
        if ln.indent < indent { break }
        if ln.indent > indent { break }
        if !strings.HasPrefix(ln.text,"- ") { break }
        rest := strings.TrimSpace(strings.TrimPrefix(ln.text,"- "))
        if rest == "" {
            if idx+1 < len(lines) && lines[idx+1].indent > indent {
                v,next,err:=parseYAMLBlock(lines,idx+1,lines[idx+1].indent); if err!=nil { return nil,next,err }
                arr=append(arr,v); idx=next
            } else { arr=append(arr,nil); idx++ }
            continue
        }
        if k, r, ok := splitYAMLKey(rest); ok {
            item := map[string]any{}
            if r=="" {
                if idx+1 < len(lines) && lines[idx+1].indent > indent { v,next,err:=parseYAMLBlock(lines,idx+1,lines[idx+1].indent); if err!=nil { return nil,next,err }; item[k]=v; idx=next } else { item[k]=map[string]any{}; idx++ }
            } else { item[k]=parseScalar(r); idx++ }
            // absorb additional map keys indented under this list item
            for idx < len(lines) && lines[idx].indent > indent {
                subIndent := lines[idx].indent
                sub, next, err := parseYAMLMap(lines, idx, subIndent); if err!=nil { return nil,next,err }
                for kk,vv := range sub { item[kk]=vv }
                idx=next
            }
            arr=append(arr,item)
        } else {
            arr=append(arr,parseScalar(rest)); idx++
        }
    }
    return arr,idx,nil
}

func splitYAMLKey(s string) (string,string,bool) {
    inS,inD,esc := false,false,false
    for i,r := range s {
        if esc { esc=false; continue }
        if r=='\\' { esc=true; continue }
        if r=='\'' && !inD { inS=!inS; continue }
        if r=='"' && !inS { inD=!inD; continue }
        if r==':' && !inS && !inD {
            key := strings.TrimSpace(s[:i])
            if key=="" { return "","",false }
            key = strings.Trim(key,"'\"")
            return key, strings.TrimSpace(s[i+1:]), true
        }
    }
    return "","",false
}

func collectBlockScalar(lines []yamlLine, idx, parentIndent int, folded, stripFinal bool) (string,int) {
    vals := []string{}
    base := -1
    for idx < len(lines) && lines[idx].indent > parentIndent {
        raw := lines[idx].raw
        if base < 0 { base = lines[idx].indent }
        if len(raw) >= base { raw = raw[base:] } else { raw = strings.TrimSpace(raw) }
        vals = append(vals, raw)
        idx++
    }
    sep := "\n"; if folded { sep=" " }
    val := strings.Join(vals, sep)
    if !stripFinal { val += "\n" }
    return val,idx
}

func parseScalar(s string) any {
    s = strings.TrimSpace(s)
    if s=="" { return "" }
    if (strings.HasPrefix(s,"'") && strings.HasSuffix(s,"'")) || (strings.HasPrefix(s,"\"") && strings.HasSuffix(s,"\"")) {
        if strings.HasPrefix(s,"\"") { if u,err:=strconv.Unquote(s); err==nil { return u } }
        return strings.ReplaceAll(strings.Trim(s,"'"), "''", "'")
    }
    low:=strings.ToLower(s)
    switch low { case "true": return true; case "false": return false; case "null", "~": return nil }
    if strings.HasPrefix(s,"[") && strings.HasSuffix(s,"]") { return parseFlowList(s[1:len(s)-1]) }
    if strings.HasPrefix(s,"{") && strings.HasSuffix(s,"}") { return parseFlowMap(s[1:len(s)-1]) }
    if i,err:=strconv.ParseInt(s,10,64); err==nil { return i }
    if f,err:=strconv.ParseFloat(s,64); err==nil && strings.IndexAny(s,".eE")>=0 { return f }
