}

func splitFlow(s string) []string {
    parts:=[]string{}; start:=0; depth:=0; inS,inD,esc:=false,false,false
    for i,r:=range s { if esc { esc=false; continue }; if r=='\\' { esc=true; continue }; if r=='\''&&!inD { inS=!inS; continue }; if r=='"'&&!inS { inD=!inD; continue }; if inS||inD { continue }; if r=='['||r=='{' { depth++ }; if r==']'||r=='}' { depth-- }; if r==','&&depth==0 { parts=append(parts,strings.TrimSpace(s[start:i])); start=i+1 } }
