    return parts
}
func parseFlowList(s string) []any { ps:=splitFlow(s); out:=[]any{}; for _,p:=range ps { out=append(out,parseScalar(p)) }; return out }
func parseFlowMap(s string) map[string]any { out:=map[string]any{}; for _,p:= range splitFlow(s) { k,r,ok:=splitYAMLKey(p); if ok { out[k]=parseScalar(r) } }; return out }

func parseEnvFile(s string) map[string]any {
    m:=map[string]any{}
    for _,line:=range strings.Split(strings.ReplaceAll(s,"\r\n","\n"),"\n") {
        line=strings.TrimSpace(line); if line==""||strings.HasPrefix(line,"#") { continue }
