    }
    return m
}

func parseTOML(s string) (map[string]any,error) {
    root:=map[string]any{}; cur:=root
    for _,line:=range strings.Split(strings.ReplaceAll(s,"\r\n","\n"),"\n") {
        line=strings.TrimSpace(stripYAMLComment(line)); if line=="" { continue }
        if strings.HasPrefix(line,"[")&&strings.HasSuffix(line,"]") { sec:=strings.Trim(line,"[] "); cur=root; for _,p:=range strings.Split(sec,".") { mm,ok:=cur[p].(map[string]any); if !ok { mm=map[string]any{}; cur[p]=mm }; cur=mm }; continue }
