    }
    return root,nil
}

func toYAML(v any, indent int) string {
    pad:=strings.Repeat(" ", indent)
    if m,ok:=toStringAnyMap(v); ok { keys:=make([]string,0,len(m)); for k:=range m { keys=append(keys,k) }; sort.Strings(keys); var b strings.Builder; for _,k:=range keys { val:=m[k]; if isScalar(val) { fmt.Fprintf(&b,"%s%s: %s\n",pad,k,yamlScalar(val)) } else { fmt.Fprintf(&b,"%s%s:\n%s",pad,k,toYAML(val,indent+2)) } }; return b.String() }
