    return pad+yamlScalar(v)+"\n"
}
func isScalar(v any) bool { if v==nil { return true }; switch v.(type) { case string,bool,int,int64,float64,float32,jsonNumber: return true }; rv:=reflectKind(v); return rv=="" }

type jsonNumber interface{}
