func yamlScalar(v any) string { if v==nil { return "null" }; switch x:=v.(type) { case string: if x=="" { return "''" }; if strings.ContainsAny(x,"\n:#[]{}") { return strconv.Quote(x) }; return x; default: return fmt.Sprint(v) } }

func toTOML(v any) string { m,ok:=toStringAnyMap(v); if !ok { return "" }; var b strings.Builder; writeTOMLMap(&b,"",m); return b.String() }
func writeTOMLMap(b *strings.Builder, prefix string, m map[string]any) { keys:=make([]string,0,len(m)); for k:=range m { keys=append(keys,k) }; sort.Strings(keys); for _,k:=range keys { if _,ok:=toStringAnyMap(m[k]); !ok { fmt.Fprintf(b,"%s = %s\n",k,tomlScalar(m[k])) } }; for _,k:=range keys { if sm,ok:=toStringAnyMap(m[k]); ok { sec:=k; if prefix!="" { sec=prefix+"."+k }; fmt.Fprintf(b,"\n[%s]\n",sec); writeTOMLMap(b,sec,sm) } } }
func tomlScalar(v any) string { switch x:=v.(type) { case string: return strconv.Quote(x); case []any: parts:=[]string{}; for _,it:=range x { parts=append(parts,tomlScalar(it)) }; return "["+strings.Join(parts,", ")+"]"; default: return fmt.Sprint(v) } }

func applyConfigYAML(cfg *Config, b []byte) error {
    v,err:=parseYAML(string(b)); if err!=nil { return err }
    m,ok:=toStringAnyMap(v); if !ok { return nil }
