    for _, raw := range strings.Split(s,"\n") {
        raw = strings.TrimRight(raw, "\r")
        if strings.TrimSpace(raw)=="" { continue }
        trimmedRaw := strings.TrimLeft(raw, " ")
        if strings.HasPrefix(trimmedRaw,"#") { continue }
        noComment := stripYAMLComment(raw)
        if strings.TrimSpace(noComment)=="" { continue }
        ind := len(noComment) - len(strings.TrimLeft(noComment," "))
