}

func stripYAMLComment(s string) string {
    inS,inD,esc := false,false,false
    for i,r := range s {
        if esc { esc=false; continue }
        if r=='\\' { esc=true; continue }
        if r=='\'' && !inD { inS=!inS; continue }
        if r=='"' && !inS { inD=!inD; continue }
        if r=='#' && !inS && !inD {
            if i==0 || s[i-1]==' ' || s[i-1]=='\t' { return strings.TrimRight(s[:i]," ") }
        }
    }
    return s
}

func parseYAMLBlock(lines []yamlLine, idx, indent int) (any,int,error) {
    if idx>=len(lines) { return nil,idx,nil }
    if strings.HasPrefix(lines[idx].text,"- ") && lines[idx].indent==indent { return parseYAMLList(lines,idx,indent) }
    return parseYAMLMap(lines,idx,indent)
}

func parseYAMLMap(lines []yamlLine, idx, indent int) (map[string]any,int,error) {
    m := map[string]any{}
    for idx < len(lines) {
        ln := lines[idx]
