        if strings.HasPrefix(ln.text,"- ") { break }
        key, rest, ok := splitYAMLKey(ln.text)
        if !ok { idx++; continue }
        if rest == "" {
            if idx+1 < len(lines) && lines[idx+1].indent > indent {
                v,next,err := parseYAMLBlock(lines, idx+1, lines[idx+1].indent); if err!=nil { return nil,next,err }
                m[key]=v; idx=next
            } else { m[key]=map[string]any{}; idx++ }
        } else if rest == "|" || rest == "|-" || rest == "|+" || strings.HasPrefix(rest, ">") {
            val,next := collectBlockScalar(lines, idx+1, indent, strings.HasPrefix(rest, ">"), strings.HasSuffix(rest,"-"))
            m[key]=val; idx=next
