func parseYAMLList(lines []yamlLine, idx, indent int) ([]any,int,error) {
    arr := []any{}
    for idx < len(lines) {
        ln := lines[idx]
        if ln.indent < indent { break }
        if ln.indent > indent { break }
        if !strings.HasPrefix(ln.text,"- ") { break }
        rest := strings.TrimSpace(strings.TrimPrefix(ln.text,"- "))
        if rest == "" {
            if idx+1 < len(lines) && lines[idx+1].indent > indent {
                v,next,err:=parseYAMLBlock(lines,idx+1,lines[idx+1].indent); if err!=nil { return nil,next,err }
