            if r=="" {
                if idx+1 < len(lines) && lines[idx+1].indent > indent { v,next,err:=parseYAMLBlock(lines,idx+1,lines[idx+1].indent); if err!=nil { return nil,next,err }; item[k]=v; idx=next } else { item[k]=map[string]any{}; idx++ }
