    m,ok:=toStringAnyMap(v); if !ok { return nil }
    if s,ok:=m["in"].(string); ok { cfg.In=&s; cfg.InputFiles=nil }
    if x,ok:=m["inputDir"]; ok { cfg.InputDir=toString(x); cfg.InputFiles=nil }
    if x,ok:=m["outputDir"]; ok { cfg.OutputDir=toString(x) }
    if x,ok:=m["outputMap"]; ok { cfg.OutputMap=toString(x) }
    if x,ok:=m["chmod"]; ok { cfg.Chmod=toString(x) }
    if x,ok:=m["leftDelim"]; ok { cfg.LeftDelim=toString(x) }
    if x,ok:=m["rightDelim"]; ok { cfg.RightDelim=toString(x) }
    if x,ok:=m["missingKey"]; ok { cfg.MissingKey=toString(x) }
    if x,ok:=m["execPipe"]; ok { cfg.ExecPipe=truthy(x) }
    if x,ok:=m["experimental"]; ok { cfg.Experimental=truthy(x) }
    if x,ok:=m["pluginTimeout"]; ok { if d,err:=time.ParseDuration(toString(x)); err==nil { cfg.PluginTimeout=d } }
    if x,ok:=m["inputFiles"]; ok { cfg.InputFiles=toStringList(x); cfg.In=nil }
    if x,ok:=m["outputFiles"]; ok { cfg.OutputFiles=toStringList(x) }
    if x,ok:=m["excludes"]; ok { cfg.Excludes=toStringList(x) }
    if x,ok:=m["excludeProcessing"]; ok { cfg.ExcludeProcessing=toStringList(x) }
    if x,ok:=m["postExec"]; ok { cfg.PostExec=toStringList(x) }
    if x,ok:=m["datasources"]; ok { applyDSMap(cfg.Datasources,x) }
    if x,ok:=m["context"]; ok { applyDSMap(cfg.Context,x) }
    if x,ok:=m["templates"]; ok { applyDSMap(cfg.Templates,x) }
    if x,ok:=m["plugins"]; ok { applyPluginMap(cfg,x) }
    return nil
}

func applyDSMap(dst map[string]*DataSource, v any) {
    m,ok:=toStringAnyMap(v); if !ok { return }
    for alias,val:=range m { if s,ok:=val.(string); ok { dst[alias]=parseDatasourceSpec(alias+"="+s); continue }; if mm,ok:=toStringAnyMap(val); ok { u:=toString(mm["url"]); ds:=parseDatasourceSpec(alias+"="+u); if hm,ok:=toStringAnyMap(mm["header"]); ok { for hk,hv:=range hm { ds.Header[hk]=toStringList(hv) } }; dst[alias]=ds } }
}
func applyPluginMap(cfg *Config, v any) { m,ok:=toStringAnyMap(v); if !ok { return }; for name,val:=range m { pc:=&PluginConfig{Timeout:cfg.PluginTimeout}; if s,ok:=val.(string); ok { pc.Cmd=s } else if mm,ok:=toStringAnyMap(val); ok { pc.Cmd=toString(mm["cmd"]); if a,ok:=mm["args"]; ok { pc.Args=toStringList(a) }; if p,ok:=mm["pipe"]; ok { pc.Pipe=truthy(p) }; if t,ok:=mm["timeout"]; ok { if d,err:=time.ParseDuration(toString(t)); err==nil { pc.Timeout=d } } }; cfg.Plugins[name]=pc } }
func toStringList(v any) []string { if v==nil { return nil }; if s,ok:=v.(string); ok { return []string{s} }; arr,err:=toAnySlice(v); if err!=nil { return nil }; out:=[]string{}; for _,it:=range arr { out=append(out,toString(it)) }; return out }
